  "rung_purposes": [
    {
      "rung": 1,
      "purpose": "Load default pressure setpoints and limits into data registers on every scan"
    },
    {
      "rung": 2,
      "purpose": "Detect PT-2001 pressure sensor wire break if reading falls below -500 (-5.00 kPa)"
    },
    {
      "rung": 3,
      "purpose": "Latch overpressure alarm M291 when pack pressure exceeds threshold D123"
    },
    {
      "rung": 4,
      "purpose": "Latch low supply air alarm M293 if supply pressure switch X22 drops while busy"
    },
    {
      "rung": 5,
      "purpose": "Reset latched alarms upon pressing fault reset button X1"
    },
    {
      "rung": 6,
      "purpose": "Evaluate summary fault M299 and drive ST20 fault beacon Y25 on alarm or tripped E-stop"
    },
    {
      "rung": 7,
      "purpose": "Control manual vent valve Y22 via pushbutton X25 in manual mode"
    },
    {
      "rung": 8,
      "purpose": "Start ST20 test cycle and transition to clamp step M201 when pallet arrives in auto mode"
    },
    {
      "rung": 9,
      "purpose": "Transition from clamp step M201 to fill step M202 once clamp closed switch confirms"
    },
    {
      "rung": 10,
      "purpose": "Run fill timeout timer T21 during fill step M202"
    },
    {
      "rung": 11,
      "purpose": "Latch fill timeout alarm M290 if timer T21 expires"
    },
    {
      "rung": 12,
      "purpose": "Transition from fill step M202 to stabilise step M203 once target pressure is reached"
    },
    {
      "rung": 13,
      "purpose": "Run stabilisation timer T22 during stabilise step M203"
    },
    {
      "rung": 14,
      "purpose": "Capture initial test pressure D110 upon timer T23 done (logic flaw: should trigger on step start)"
    },
    {
      "rung": 15,
      "purpose": "Transition from stabilise step M203 to test step M204 when stabilisation timer T22 expires"
    },
    {
      "rung": 16,
      "purpose": "Run test window timer T23 during test step M204"
    },
    {
      "rung": 17,
      "purpose": "Sample final pressure D111 and calculate pressure decay D112 when test timer T23 expires"
    },
    {
      "rung": 18,
      "purpose": "Evaluate leak test decay against limit D120 and set PASS (M210) or FAIL (M211)"
    },
    {
      "rung": 19,
      "purpose": "Transition from test step M204 to vent step M205 when test timer T23 expires"
    },
    {
      "rung": 20,
      "purpose": "Abort active test cycle to vent step M205 and flag failure on summary fault M299"
    },
    {
      "rung": 21,
      "purpose": "Run vent timer T200 during vent step M205"
    },
    {
      "rung": 22,
      "purpose": "Transition from vent step M205 to unclamp step M206 once vented and timer T200 done"
    },
    {
      "rung": 23,
      "purpose": "Transition from unclamp step M206 to complete step M207 once clamp open switch confirms"
    },
    {
      "rung": 24,
      "purpose": "Clear cycle complete step M207 and busy flag M200 once pallet departs"
    },
    {
      "rung": 25,
      "purpose": "Energize clamp close solenoid Y20 during clamping, testing, and venting steps"
    },
    {
      "rung": 26,
      "purpose": "Energize fill valve Y21 during fill step M202 if no fault is active"
    },
    {
      "rung": 27,
      "purpose": "Open vent valve Y22 during vent step M205 or on overpressure alarm M291"
    },
    {
      "rung": 28,
      "purpose": "Signal PASS (Y23) or FAIL (Y24) to line controller during cycle complete step M207"
    },
    {
      "rung": 29,
      "purpose": "End of ladder program execution"
    }
